const listPositionsByCompany = `-- name: ListPositionsByCompany :many
SELECT p.id, p.company_id, p.code, p.title, p.status, p.sort_order, p.created_at, p.updated_at, p.deleted_at FROM oikumenea.company_positions p
WHERE p.company_id = $1 AND p.deleted_at IS NULL AND p.status = 'active'
  AND ($2 = '' OR p.id::text > $2)
  AND (
    $3 = '' OR
    ($3 = 'filled' AND EXISTS (
      SELECT 1 FROM oikumenea.company_appointments a
      WHERE a.position_id = p.id AND a.status = 'active' AND a.deleted_at IS NULL)) OR
    ($3 = 'vacant' AND NOT EXISTS (
      SELECT 1 FROM oikumenea.company_appointments a
      WHERE a.position_id = p.id AND a.status = 'active' AND a.deleted_at IS NULL))
  )
ORDER BY p.id
LIMIT $4
`

